"""A parser for standard 5-field cron expressions.

A cron expression has the form::

    minute hour day_of_month month day_of_week

Each field accepts a wildcard ("*"), a single value ("5"), a range
("1-5"), a comma-separated list ("1,3,5"), a step ("*/15"), or a
stepped range ("1-30/5").

The public entry point is ``parse_cron_expression``, which returns a
``CronSchedule``. Call ``.describe()`` on the result to get an English
sentence describing when the schedule runs.

The module is organized in two halves:

1. ``CronField`` / ``CronSchedule`` -- the data model, including the
   ``describe()`` method that turns a parsed schedule into English.
2. ``parse_cron_expression`` and its helpers -- turning raw text into
   that data model.
"""

from dataclasses import dataclass
from typing import List, Sequence, Tuple


class CronParseError(ValueError):
    """Raised when a cron expression, or one of its fields, is invalid."""


# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------

@dataclass(frozen=True)
class FieldSpec:
    """The name and valid value range for one of the 5 cron fields."""

    name: str
    minimum: int
    maximum: int


# Order matches the field order in a cron expression.
FIELD_SPECS: Tuple[FieldSpec, ...] = (
    FieldSpec("minute", 0, 59),
    FieldSpec("hour", 0, 23),
    FieldSpec("day_of_month", 1, 31),
    FieldSpec("month", 1, 12),
    FieldSpec("day_of_week", 0, 6),
)

WEEKDAY_NAMES: Tuple[str, ...] = (
    "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday",
)

# Index 0 is unused so that MONTH_NAMES[1] == "January", matching cron's 1-12 months.
MONTH_NAMES: Tuple[str, ...] = (
    "", "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December",
)


# ---------------------------------------------------------------------------
# Small text helpers shared by the parser and the describer
# ---------------------------------------------------------------------------

def is_wildcard_expression(expression: str) -> bool:
    """True for a bare "*", meaning "any value"."""
    return expression == "*"


def has_step(expression: str) -> bool:
    """True for expressions of the form 'BASE/STEP', e.g. '*/15' or '1-30/5'."""
    return "/" in expression


def base_expression(expression: str) -> str:
    """The part of an expression before '/STEP'. Returns the input unchanged if there is no step."""
    return expression.split("/", 1)[0]


def step_value(expression: str) -> int:
    """The STEP in a 'BASE/STEP' expression. Only valid when has_step() is True."""
    return int(expression.split("/", 1)[1])


def is_simple_range(expression: str) -> bool:
    """True for a plain 'LOW-HIGH' expression, e.g. '1-5' -- no list, no step."""
    return "-" in expression and "," not in expression and "/" not in expression


def ordinal(number: int) -> str:
    """Render a number with its English ordinal suffix, e.g. 1 -> '1st', 22 -> '22nd'."""
    if 11 <= number % 100 <= 13:
        suffix = "th"
    else:
        suffix = {1: "st", 2: "nd", 3: "rd"}.get(number % 10, "th")
    return f"{number}{suffix}"


def join_with_and(items: Sequence[str]) -> str:
    """Join items the way English lists do: 'a', 'a and b', or 'a, b, and c'."""
    items = list(items)
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return f"{items[0]} and {items[1]}"
    return ", ".join(items[:-1]) + f", and {items[-1]}"


# ---------------------------------------------------------------------------
# Data model
# ---------------------------------------------------------------------------

@dataclass(frozen=True)
class CronField:
    """One parsed field of a cron expression, e.g. the 'hour' field."""

    raw_expression: str
    values: Tuple[int, ...]


@dataclass(frozen=True)
class CronSchedule:
    """A fully parsed 5-field cron expression."""

    minute: CronField
    hour: CronField
    day_of_month: CronField
    month: CronField
    day_of_week: CronField

    def describe(self) -> str:
        """Build a human-readable English description of this schedule."""
        if self._runs_every_minute():
            return "Every minute"
        if self._is_plain_minute_interval():
            return f"Every {step_value(self.minute.raw_expression)} minutes"
        if self._is_plain_hour_interval():
            return f"Every {step_value(self.hour.raw_expression)} hours, on the hour"

        time_description = self._describe_time_of_day()
        date_description = self._describe_date_restriction()
        return f"{time_description} {date_description}".strip()

    # -- recognizing a few common shorthand patterns --------------------

    def _runs_every_minute(self) -> bool:
        return all(is_wildcard_expression(field.raw_expression) for field in self._all_fields())

    def _is_plain_minute_interval(self) -> bool:
        """True for schedules like '*/15 * * * *': a bare minute step, nothing else restricted."""
        return (
            has_step(self.minute.raw_expression)
            and is_wildcard_expression(base_expression(self.minute.raw_expression))
            and is_wildcard_expression(self.hour.raw_expression)
            and is_wildcard_expression(self.day_of_month.raw_expression)
            and is_wildcard_expression(self.month.raw_expression)
            and is_wildcard_expression(self.day_of_week.raw_expression)
        )

    def _is_plain_hour_interval(self) -> bool:
        """True for schedules like '0 */2 * * *': a bare hour step, run on the hour."""
        return (
            has_step(self.hour.raw_expression)
            and is_wildcard_expression(base_expression(self.hour.raw_expression))
            and self.minute.values == (0,)
            and is_wildcard_expression(self.day_of_month.raw_expression)
            and is_wildcard_expression(self.month.raw_expression)
            and is_wildcard_expression(self.day_of_week.raw_expression)
        )

    def _all_fields(self) -> Tuple[CronField, ...]:
        return (self.minute, self.hour, self.day_of_month, self.month, self.day_of_week)

    # -- describing the time-of-day portion ("At 08:30", "At minute ...") --

    def _describe_time_of_day(self) -> str:
        if self._is_single_value(self.minute) and self._is_single_value(self.hour):
            return self._describe_exact_time(self.hour.values[0], self.minute.values[0])
        minute_text = self._describe_minute_field()
        hour_text = self._describe_hour_field()
        return f"At {minute_text} past {hour_text}"

    @staticmethod
    def _is_single_value(field: CronField) -> bool:
        return len(field.values) == 1

    @staticmethod
    def _describe_exact_time(hour: int, minute: int) -> str:
        if hour == 0 and minute == 0:
            return "At midnight"
        return f"At {hour:02d}:{minute:02d}"

    def _describe_minute_field(self) -> str:
        if is_wildcard_expression(self.minute.raw_expression):
            return "every minute"
        return f"minute {join_with_and([str(value) for value in self.minute.values])}"

    def _describe_hour_field(self) -> str:
        if is_wildcard_expression(self.hour.raw_expression):
            return "every hour"
        return f"hour {join_with_and([str(value) for value in self.hour.values])}"

    # -- describing the date portion ("on the 1st of every month", etc.) --

    def _describe_date_restriction(self) -> str:
        clauses = []
        if not is_wildcard_expression(self.day_of_month.raw_expression):
            clauses.append(self._describe_day_of_month_and_month())
        elif not is_wildcard_expression(self.month.raw_expression):
            clauses.append(self._describe_month_only())
        if not is_wildcard_expression(self.day_of_week.raw_expression):
            clauses.append(self._describe_day_of_week())
        return " ".join(clauses)

    def _describe_day_of_month_and_month(self) -> str:
        day_text = self._describe_ordinal_field(self.day_of_month)
        if is_wildcard_expression(self.month.raw_expression):
            return f"on {day_text} of every month"
        month_text = self._describe_named_field(self.month, MONTH_NAMES)
        return f"on {day_text} of {month_text}"

    def _describe_month_only(self) -> str:
        return f"in {self._describe_named_field(self.month, MONTH_NAMES)}"

    def _describe_day_of_week(self) -> str:
        return f"on {self._describe_named_field(self.day_of_week, WEEKDAY_NAMES)}"

    @staticmethod
    def _describe_ordinal_field(field: CronField) -> str:
        if is_simple_range(field.raw_expression):
            return f"the {ordinal(field.values[0])} through the {ordinal(field.values[-1])}"
        return f"the {join_with_and([ordinal(value) for value in field.values])}"

    @staticmethod
    def _describe_named_field(field: CronField, names: Sequence[str]) -> str:
        if is_simple_range(field.raw_expression):
            return f"{names[field.values[0]]} through {names[field.values[-1]]}"
        return join_with_and([names[value] for value in field.values])


# ---------------------------------------------------------------------------
# Parsing
# ---------------------------------------------------------------------------

def parse_cron_expression(expression: str) -> CronSchedule:
    """Parse a standard 5-field cron expression into a CronSchedule.

    Raises CronParseError if the expression is malformed.
    """
    field_texts = split_into_fields(expression)
    minute, hour, day_of_month, month, day_of_week = (
        parse_field(text, spec) for text, spec in zip(field_texts, FIELD_SPECS)
    )
    return CronSchedule(minute, hour, day_of_month, month, day_of_week)


def split_into_fields(expression: str) -> List[str]:
    """Split a cron expression into its 5 whitespace-separated fields."""
    fields = expression.split()
    if len(fields) != 5:
        raise CronParseError(
            "A cron expression must have exactly 5 fields "
            "(minute hour day_of_month month day_of_week), "
            f"got {len(fields)} in {expression!r}"
        )
    return fields


def parse_field(raw_field: str, spec: FieldSpec) -> CronField:
    """Parse one field, e.g. '1,3,5' or '*/15', honoring the given valid range."""
    resolved_values = set()
    for part in raw_field.split(","):
        resolved_values.update(parse_field_part(part, spec))
    return CronField(raw_expression=raw_field, values=tuple(sorted(resolved_values)))


def parse_field_part(part: str, spec: FieldSpec) -> List[int]:
    """Parse a single comma-separated part of a field, e.g. '*/15', '1-5', or '42'."""
    if part == "":
        raise CronParseError(f"{spec.name} field {part!r} contains an empty value")
    base_text, step = split_off_step(part, spec)
    base_values = parse_base_values(base_text, spec)
    return base_values[::step]


def split_off_step(part: str, spec: FieldSpec) -> Tuple[str, int]:
    """Split 'BASE/STEP' into (BASE, STEP), defaulting STEP to 1 when there is none."""
    if "/" not in part:
        return part, 1
    base_text, step_text = part.split("/", 1)
    if not step_text.isdigit() or int(step_text) == 0:
        raise CronParseError(f"{spec.name} field has an invalid step {step_text!r} in {part!r}")
    return base_text, int(step_text)


def parse_base_values(base_text: str, spec: FieldSpec) -> List[int]:
    """Parse the part of a field before any '/step', e.g. '*', '1-5', or '42'."""
    if base_text == "*":
        return list(range(spec.minimum, spec.maximum + 1))
    if "-" in base_text:
        return parse_range(base_text, spec)
    return [parse_single_value(base_text, spec)]


def parse_range(base_text: str, spec: FieldSpec) -> List[int]:
    """Parse a 'LOW-HIGH' expression into the inclusive list of values it spans."""
    low_text, _, high_text = base_text.partition("-")
    low = parse_single_value(low_text, spec)
    high = parse_single_value(high_text, spec)
    if low > high:
        raise CronParseError(f"{spec.name} range {base_text!r} starts after it ends")
    return list(range(low, high + 1))


def parse_single_value(text: str, spec: FieldSpec) -> int:
    """Parse and validate a single integer value against a field's valid range."""
    if not text.isdigit():
        raise CronParseError(f"{spec.name} field contains a non-numeric value {text!r}")
    value = int(text)
    if not spec.minimum <= value <= spec.maximum:
        raise CronParseError(
            f"{spec.name} value {value} is out of range ({spec.minimum}-{spec.maximum})"
        )
    return value


# ---------------------------------------------------------------------------
# Demo
# ---------------------------------------------------------------------------

if __name__ == "__main__":
    examples = [
        "* * * * *",
        "0 12 * * 1-5",
        "*/15 * * * *",
        "0 0 1 * *",
        "30 8 * * 1,3,5",
        "0 */2 * * *",
    ]
    for expression in examples:
        schedule = parse_cron_expression(expression)
        print(f"{expression!r:20} -> {schedule.describe()}")
