        )

    unit = _pluralize("minute", len(minute.values))
    values = [str(value) for value in minute.values]
    return f"at {unit} {_join_english(values)}"


def _describe_hour_windows(hour: CronField) -> str:
    part = _only_part(hour)

    if len(hour.values) == 1:
        return f"the {hour.values[0]:02d}:00 hour"

    if part is not None and part.kind == PartKind.WILDCARD:
        return (
            f"every {_ordinal(part.step)} hour, "
            f"starting with 00:00"
        )

    if part is not None and part.kind == PartKind.RANGE:
        start = f"{part.start:02d}:00"
        end = f"{part.end:02d}:00"

        if part.step == 1:
            return f"the hours from {start} through {end}"

        return (
            f"every {_ordinal(part.step)} hour "
            f"from {start} through {end}"
        )

    labels = [f"{value:02d}:00" for value in hour.values]
    return f"the {_join_english(labels)} hours"


def _describe_date(
    day_of_month: CronField,
    month: CronField,
    day_of_week: CronField,
) -> str:
    has_day_of_month = not day_of_month.is_unrestricted
    has_month = not month.is_unrestricted
    has_day_of_week = not day_of_week.is_unrestricted

    month_text = _describe_months(month) if has_month else ""

    # Traditional cron treats day-of-month and day-of-week as alternatives
    # when both are restricted.
    if has_day_of_month and has_day_of_week:
        date_text = (
            f"when the day of the month is "
            f"{_describe_days_of_month(day_of_month)} "
            f"or the weekday is {_describe_weekdays(day_of_week)}"
        )
        return f"{date_text}, in {month_text}" if has_month else date_text

    if has_day_of_month:
        day_text = _describe_days_of_month(day_of_month)
        if has_month:
            return f"on {day_text} of {month_text}"
        return f"on {day_text} of every month"

    if has_day_of_week:
        weekday_text = _describe_weekdays(day_of_week)
        if has_month:
            return f"on {weekday_text} in {month_text}"
        return f"on {weekday_text}"

    if has_month:
        return f"in {month_text}"

    return ""


def _describe_days_of_month(field: CronField) -> str:
    part = _only_part(field)

    if (
        part is not None
        and part.kind == PartKind.RANGE
        and part.step == 1
        and part.start != part.end
    ):
        return f"the {_ordinal(part.start)} through the {_ordinal(part.end)}"

    ordinals = [_ordinal(value) for value in field.values]
    return f"the {_join_english(ordinals)}"


def _describe_months(field: CronField) -> str:
    return _describe_named_values(field, MONTH_NAMES, index_offset=1)


def _describe_weekdays(field: CronField) -> str:
    return _describe_named_values(field, WEEKDAY_NAMES, index_offset=0)


def _describe_named_values(
    field: CronField,
    names: Sequence[str],
    index_offset: int,
) -> str:
    part = _only_part(field)

    if (
        part is not None
        and part.kind == PartKind.RANGE
        and part.step == 1
        and part.start != part.end
    ):
        start_name = names[part.start - index_offset]
        end_name = names[part.end - index_offset]
        return f"{start_name} through {end_name}"

    selected_names = [
        names[value - index_offset]
        for value in field.values
    ]
    return _join_english(selected_names)


def _only_part(field: CronField) -> CronFieldPart | None:
    if len(field.parts) == 1:
        return field.parts[0]
    return None


def _wildcard_step(field: CronField) -> int | None:
    part = _only_part(field)

    if (
        part is not None
        and part.kind == PartKind.WILDCARD
        and part.step > 1
    ):
        return part.step

    return None


def _ordinal(value: int) -> str:
    remainder = value % 100

    if 11 <= remainder <= 13:
        suffix = "th"
    else:
        suffix = {
            1: "st",
            2: "nd",
            3: "rd",
        }.get(value % 10, "th")

    return f"{value}{suffix}"


def _join_english(items: Sequence[str]) -> str:
    if not items:
        return ""

    if len(items) == 1:
        return items[0]

    if len(items) == 2:
        return f"{items[0]} and {items[1]}"

    return f"{', '.join(items[:-1])}, and {items[-1]}"


def _pluralize(word: str, count: int) -> str:
    return word if count == 1 else f"{word}s"


def _capitalize(text: str) -> str:
    if not text:
        return text
    return text[0].upper() + text[1:]
```

Example usage:

```python
schedule = parse_cron("30 8 * * 1,3,5")

print(schedule.hour.values)   # (8,)
print(schedule.describe())    # At 08:30 on Monday, Wednesday, and Friday
```
